use std::collections::HashSet;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};

use tauri::ipc::Channel;
use tauri::{AppHandle, Emitter, Manager, State};

use crate::clean::ArtifactKey;
use crate::model::{
    AppInfo, Category, CleanEvent, CleanItem, CleanReport, Overview, ProjectScan, TargetScan,
};

/// Artifact directories returned by the latest project scan (inactive projects only).
/// `clean` refuses any artifact path that isn't in here.
#[derive(Default)]
struct AppState {
    allowed_artifacts: Arc<Mutex<HashSet<ArtifactKey>>>,
    /// Mica was applied to the main window (the page may then use a transparent background).
    vibrancy: AtomicBool,
    /// An elevated task is running: the window refuses to close until it finishes.
    admin_running: AtomicBool,
}

/// Emitted when the user tries to close the window while an elevated task is running.
const CLOSE_BLOCKED_EVENT: &str = "close-blocked";

/// Run blocking work off the async runtime.
async fn blocking<T: Send + 'static>(f: impl FnOnce() -> T + Send + 'static) -> Result<T, String> {
    tauri::async_runtime::spawn_blocking(f)
        .await
        .map_err(|e| e.to_string())
}

/// Disks, WSL/Docker virtual disks, hibernation file and recycle bin.
#[tauri::command]
#[specta::specta]
async fn get_overview() -> Result<Overview, String> {
    blocking(scan::overview).await
}

/// Dev caches and Windows junk found on this machine (all categories when `category` is null).
#[tauri::command]
#[specta::specta]
async fn scan_targets(category: Option<Category>) -> Result<TargetScan, String> {
    blocking(move || {
        let (targets, errors) = scan::targets(category);
        TargetScan { targets, errors }
    })
    .await
}

/// Projects with build artifacts under `roots`. Projects modified within `active_days` are
/// returned with `active: true` and can never be cleaned.
#[tauri::command]
#[specta::specta]
async fn scan_projects(
    state: State<'_, AppState>,
    roots: Vec<String>,
    active_days: u32,
) -> Result<ProjectScan, String> {
    let allowed = state.allowed_artifacts.clone();
    blocking(move || {
        let (projects, errors) = projects::scan(&roots, active_days);
        let keys: HashSet<ArtifactKey> = projects
            .iter()
            .filter(|p| !p.active)
            .flat_map(|p| {
                p.artifacts
                    .iter()
                    .map(|a| (p.distro.clone(), a.path.clone()))
            })
            .collect();
        *allowed.lock().unwrap_or_else(|e| e.into_inner()) = keys;
        ProjectScan { projects, errors }
    })
    .await
}

/// Clean the selected items, streaming progress to `on_event`. With `dry_run`, only measure.
/// Real runs are appended to the history.
#[tauri::command]
#[specta::specta]
async fn clean(
    app: AppHandle,
    state: State<'_, AppState>,
    items: Vec<CleanItem>,
    dry_run: bool,
    record_history: bool,
    on_event: Channel<CleanEvent>,
) -> Result<CleanReport, String> {
    let allowed = state
        .allowed_artifacts
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .clone();
    let report = blocking(move || {
        clean::run(&items, dry_run, &allowed, |e| {
            let _ = on_event.send(e);
        })
    })
    .await?;
    if !dry_run && record_history {
        history::append(&app, &report)?;
    }
    Ok(report)
}

/// Run a task that needs administrator rights (one UAC prompt) or restarts WSL/Docker.
/// A declined UAC prompt comes back as `skipped`.
#[tauri::command]
#[specta::specta]
async fn run_admin_task(
    app: AppHandle,
    state: State<'_, AppState>,
    task: admin::AdminTask,
    record_history: bool,
) -> Result<model::ItemResult, String> {
    let started_at = fsutil::now_ms();
    state.admin_running.store(true, Ordering::Relaxed);
    let result = blocking(move || admin::run(&task)).await;
    state.admin_running.store(false, Ordering::Relaxed);
    let result = result?;
    if record_history && result.status != model::ItemStatus::Skipped {
        let report = CleanReport {
            dry_run: false,
            freed: result.freed,
            results: vec![result.clone()],
            started_at,
            finished_at: fsutil::now_ms(),
        };
        history::append(&app, &report)?;
    }
    Ok(result)
}

/// Window effect status and the project folders suggested on first run.
#[tauri::command]
#[specta::specta]
async fn get_app_info(state: State<'_, AppState>) -> Result<AppInfo, String> {
    let vibrancy = state.vibrancy.load(Ordering::Relaxed);
    blocking(move || AppInfo {
        vibrancy,
        default_project_roots: projects::default_roots(),
    })
    .await
}

/// Match the native title bar and the Mica tint to the app's theme (not only Windows'),
/// otherwise a light sidebar sits on a dark material and becomes muddy.
#[tauri::command]
#[specta::specta]
async fn set_window_theme(
    app: AppHandle,
    state: State<'_, AppState>,
    dark: bool,
    follow_system: bool,
) -> Result<(), String> {
    let Some(window) = app.get_webview_window("main") else {
        return Ok(());
    };
    let theme = match (follow_system, dark) {
        (true, _) => None,
        (false, true) => Some(tauri::Theme::Dark),
        (false, false) => Some(tauri::Theme::Light),
    };
    window.set_theme(theme).map_err(|e| e.to_string())?;
    if state.vibrancy.load(Ordering::Relaxed) {
        window_vibrancy::apply_mica(&window, Some(dark)).map_err(|e| e.to_string())?;
    }
    Ok(())
}

/// Show a project folder in File Explorer. WSL projects (`distro` set, Linux `path`) are opened
/// through `\\wsl.localhost`. Only existing directories are opened, never files.
#[tauri::command]
#[specta::specta]
async fn open_folder(path: String, distro: Option<String>) -> Result<(), String> {
    blocking(move || {
        let dir = match distro {
            Some(d) => wsl::to_unc(&d, &path).ok_or_else(|| format!("invalid WSL path: {path}"))?,
            None => path,
        };
        if !std::path::Path::new(&dir).is_dir() {
            return Err(format!("folder not found: {dir}"));
        }
        tauri_plugin_opener::open_path(&dir, None::<&str>).map_err(|e| e.to_string())
    })
    .await?
}

/// Past clean runs, newest first.
#[tauri::command]
#[specta::specta]
async fn get_history(app: AppHandle, limit: u32) -> Result<Vec<CleanReport>, String> {
    history::list(&app, limit as usize)
}

fn specta_builder() -> tauri_specta::Builder<tauri::Wry> {
    tauri_specta::Builder::<tauri::Wry>::new().commands(tauri_specta::collect_commands![
        get_overview,
        scan_targets,
        scan_projects,
        clean,
        get_history,
        get_app_info,
        set_window_theme,
        run_admin_task,
        open_folder,
    ])
}

#[cfg(any(debug_assertions, test))]
const BINDINGS_PATH: &str = "../src/lib/bindings.ts";

#[cfg(any(debug_assertions, test))]
fn export_bindings(builder: &tauri_specta::Builder<tauri::Wry>) {
    builder
        .export(specta_typescript::Typescript::default(), BINDINGS_PATH)
        .expect("failed to export TypeScript bindings");
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    let builder = specta_builder();
    #[cfg(debug_assertions)]
    export_bindings(&builder);

    tauri::Builder::default()
        .plugin(tauri_plugin_log::Builder::new().build())
        .plugin(tauri_plugin_store::Builder::new().build())
        .plugin(tauri_plugin_window_state::Builder::new().build())
        .plugin(tauri_plugin_dialog::init())
        .plugin(tauri_plugin_os::init())
        .plugin(tauri_plugin_opener::init())
        .manage(AppState::default())
        .invoke_handler(builder.invoke_handler())
        .on_window_event(|window, event| {
            // Closing mid-task would leave the user without the result (and WSL possibly down),
            // so refuse and let the page explain why.
            if let tauri::WindowEvent::CloseRequested { api, .. } = event
                && window
                    .state::<AppState>()
                    .admin_running
                    .load(Ordering::Relaxed)
            {
                api.prevent_close();
                let _ = window.emit(CLOSE_BLOCKED_EVENT, ());
            }
        })
        .setup(move |app| {
            builder.mount_events(app);
            if let Some(window) = app.get_webview_window("main") {
                // Mica needs Windows 11; on failure the page keeps its opaque background.
                let applied = window_vibrancy::apply_mica(&window, None).is_ok();
                app.state::<AppState>()
                    .vibrancy
                    .store(applied, Ordering::Relaxed);
            }
            Ok(())
        })
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

#[cfg(test)]
mod tests {
    /// `cargo test export_bindings` regenerates `src/lib/bindings.ts` without starting the app.
    #[test]
    fn export_bindings() {
        super::export_bindings(&super::specta_builder());
        let ts = std::fs::read_to_string(super::BINDINGS_PATH).unwrap();
        for name in [
            "getOverview",
            "scanTargets",
            "scanProjects",
            "clean",
            "getHistory",
            "CleanEvent",
        ] {
            assert!(ts.contains(name), "bindings missing {name}");
        }
    }
}

/// Read-only smoke test against the real machine (never deletes; `clean` runs as a dry run).
/// Run with: `cargo test smoke -- --ignored --nocapture`
#[cfg(test)]
mod smoke {
    use super::*;
    use std::time::Instant;

    #[test]
    #[ignore]
    fn smoke_real_machine() {
        let t = Instant::now();
        let ov = scan::overview();
        println!(
            "== overview ({:?})\n{}",
            t.elapsed(),
            serde_json::to_string_pretty(&ov).unwrap()
        );

        let t = Instant::now();
        let (targets, errors) = scan::targets(None);
        println!("== targets ({:?}) errors={errors:?}", t.elapsed());
        for x in &targets {
            println!(
                "{:<34} {:>10.1} MB  blocked={:?}",
                x.id,
                x.size.unwrap_or(-1.0) / 1048576.0,
                x.blocked_by
            );
        }

        let t = Instant::now();
        let home_ws = r"\\wsl.localhost\Ubuntu-24.04\home\neon\workspace".to_string();
        let (projects, errors) = projects::scan(&[home_ws], 14);
        println!("== projects ({:?}) errors={errors:?}", t.elapsed());
        for p in &projects {
            let arts: Vec<String> = p
                .artifacts
                .iter()
                .map(|a| format!("{}={:.0}MB", a.name, a.size / 1048576.0))
                .collect();
            println!(
                "{:<28} {:<6} active={:<5} {:>8.1} MB  {}",
                p.name,
                p.kind,
                p.active,
                p.size / 1048576.0,
                arts.join(" ")
            );
        }

        let items: Vec<model::CleanItem> = targets
            .iter()
            .map(|t| model::CleanItem::Target { id: t.id.clone() })
            .collect();
        let report = clean::run(&items, true, &HashSet::new(), |_| {});
        println!(
            "== dry run: {:.1} MB would be freed",
            report.freed / 1048576.0
        );
        for r in report
            .results
            .iter()
            .filter(|r| r.status != model::ItemStatus::Done)
        {
            println!("  {:?} {} {:?}", r.status, r.key, r.message);
        }
        assert!(report.dry_run);
    }
}
